def emit(message: str) -> None:
    line = str(message)
    print(line, flush=True)
    log = WORKING_ROOT / OUTPUT_NAME / "run.log"
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("a", buffering=1) as handle:
        handle.write(line + "\n")


def phase(name: str, **fields) -> None:
    emit(json.dumps({"phase": name, **fields}, ensure_ascii=False, default=str))


def sha256_file(path: Path) -> str:
    import hashlib

    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def check_sha(label: str, path: Path, expected: str) -> str:
    actual = sha256_file(path)
    if actual != expected:
        if LOCAL_TEST:
            phase("sha_mismatch_ignored_local_test", label=label, actual=actual)
            return actual
        raise RuntimeError(f"{label} SHA mismatch: {actual} != {expected}")
    return actual


def extract_bundle(target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    raw = base64.b64decode(EMBEDDED_KRONOS_ARCHIVE_B64.strip())
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as archive:
        archive.extractall(target)
    root = target / "Kronos"
    if not (root / "model").is_dir():
        raise RuntimeError(f"Embedded archive missing model/ under {root}")
    return root


def download_model_repo(target: Path) -> Path:
    override = os.environ.get("KRONOS_MODEL_SNAPSHOT")
    if override:
        return Path(override)
    target.mkdir(parents=True, exist_ok=True)
    try:
        from modelscope.hub.snapshot_download import snapshot_download
    except ImportError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "modelscope"])
        from modelscope.hub.snapshot_download import snapshot_download
    phase("download_model_repo", repo=MODEL_REPO)
    snapshot_download(MODEL_REPO, local_dir=str(target))
    return target


def resolve_tokenizer(snapshot: Path) -> Path:
    tokenizer = snapshot / "tokenizer"
    if not (tokenizer / "config.json").is_file():
        matches = sorted(snapshot.glob("**/tokenizer/config.json"))
        if not matches:
            raise RuntimeError(f"Tokenizer not found under {snapshot}")
        tokenizer = matches[0].parent
    sha = check_sha("tokenizer", tokenizer / "model.safetensors", EXPECTED_TOKENIZER_SHA256)
    phase("tokenizer_ready", path=str(tokenizer), sha256=sha)
    return tokenizer


def resolve_release_predictor(snapshot: Path, expected: str) -> Path:
    """Same lookup as the val-gen-ic / cosine-pilot kernels (by SHA in the snapshot)."""
    candidates = [snapshot / "best_model", snapshot]
    candidates += [path.parent for path in sorted(snapshot.glob("**/model.safetensors"))]
    for candidate in candidates:
        weights = candidate / "model.safetensors"
        if candidate.name == "tokenizer" or not weights.is_file():
            continue
        if not (candidate / "config.json").is_file():
            continue
        if LOCAL_TEST or sha256_file(weights) == expected:
            return candidate.resolve()
    raise RuntimeError(f"Release predictor with sha {expected} not found under {snapshot}")


def find_dataset_checkpoint(input_root: Path, label: str, patterns) -> Path:
    matches = set()
    for pattern in patterns:
        for path in input_root.glob(pattern):
            if (path / "config.json").is_file() and (path / "model.safetensors").is_file():
                matches.add(path.resolve())
    if len(matches) != 1:
        raise RuntimeError(f"{label}: expected one checkpoint, found {sorted(matches)}")
    return next(iter(matches))


def build_tasks(checkpoints, arms, dates) -> list[dict]:
    """Checkpoint-major, then arm, then date: Seg9's 18 shards come first."""
    return [
        {"checkpoint": ckpt["label"], "arm": arm["name"], "date": date}
        for ckpt in checkpoints
        for arm in arms
        for date in dates
    ]


def shard_file(shards: Path, task: dict) -> Path:
    return shards / f"{task['checkpoint']}__{task['arm']}_{task['date']}.csv.gz"


def paired_stats(a: dict, b: dict) -> dict | None:
    """Paired by-date difference a - b over the common dates (t with n-1 df)."""
    dates = sorted(set(a) & set(b))
    diffs = [float(a[d]) - float(b[d]) for d in dates
             if a[d] is not None and b[d] is not None]
    n = len(diffs)
    if n == 0:
        return None
    mean = sum(diffs) / n
    if n > 1:
        var = sum((x - mean) ** 2 for x in diffs) / (n - 1)
        sd = math.sqrt(var)
        se = sd / math.sqrt(n)
        t = mean / se if se > 0 else None
    else:
        sd = se = t = None
    return {
        "n": n,
        "mean_diff": mean,
        "sd_diff": sd,
        "se_diff": se,
        "t": t,
        "wins": int(sum(1 for x in diffs if x > 0)),
        "dates": dates,
        "note": "paired t ignores label-window overlap between adjacent dates (optimistic)",
    }


def top_bottom_by_date(frame, frac: float = 0.1) -> dict:
    out = {}
    for asof, group in frame.groupby("asof_date"):
        n = len(group)
        k = max(1, int(round(n * frac)))
        ordered = group.sort_values("predicted_return_d10")
        out[str(asof)] = float(
            ordered["return_10d"].iloc[-k:].mean() - ordered["return_10d"].iloc[:k].mean()
        )
    return out


class _NullRun:
    def log(self, payload, step=None) -> None:  # noqa: D401 - no-op
        return None


class SafeRun:
    """SwanLab wrapper: a logging failure must never stop the evaluation."""

    def __init__(self, run=None):
        self.run = run
        self.errors = 0

    def log(self, payload, step=None) -> None:
        if self.run is None:
            return
        try:
            self.run.log(payload, step=step)
        except Exception as error:  # noqa: BLE001
            self.errors += 1
            if self.errors <= 5:
                phase("swanlab_log_error", error=repr(error), keys=sorted(payload)[:6])


def resolve_swanlab_key() -> tuple[str, str]:
    key = os.environ.get("SWANLAB_API_KEY", "").strip()
    if key:
        return key, "env"
    try:
        from kaggle_secrets import UserSecretsClient

        key = (UserSecretsClient().get_secret("SWANLAB_API_KEY") or "").strip()
        if key:
            return key, "kaggle_secret"
    except Exception:  # noqa: BLE001 - secret not attached to this kernel
        pass
    return SWANLAB_API_KEY_FALLBACK, "fallback"


def start_swanlab(config: dict):
    if LOCAL_TEST or os.environ.get("KRONOS_DISABLE_SWANLAB") == "1":
        phase("swanlab_disabled")
        return None, _NullRun()
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", "--disable-pip-version-check",
                        "--progress-bar", "off", "-q", "swanlab"], check=True)
        import swanlab

        api_key, key_source = resolve_swanlab_key()
        swanlab.login(api_key=api_key)
        run = swanlab.init(
            project=SWANLAB_PROJECT,
            workspace=SWANLAB_WORKSPACE,
            experiment_name=OUTPUT_NAME,
            id=SWANLAB_RUN_ID,
            resume="allow",
            tags=["kronos-base", "beta-v2.1", "c1", "sealed-oos", "gen-return",
                  "prod-n5", "final-eval", "cosine-pilot-seg9", "dual-t4"],
            config=config,
        )
        phase("swanlab_ready", url=SWANLAB_URL, key_source=key_source)
        return swanlab, SafeRun(run)
    except Exception as error:  # noqa: BLE001
        phase("swanlab_unavailable", error=repr(error))
        return None, _NullRun()


class OOSScorer:
    """Parent-side bookkeeping: per-shard progress + per-checkpoint final scoring."""

    def __init__(self, working: Path, shards: Path, dates, records_count: int,
                 checkpoints, arms, checkpoint_dirs: dict, model_shas: dict,
                 score_predictions, build_summary, run=None, started=None,
                 expected_rows=None):
        self.working = Path(working)
        self.results = self.working / "results"
        self.results.mkdir(parents=True, exist_ok=True)
        self.shards = Path(shards)
        self.dates = list(dates)
        self.records_count = int(records_count)
        self.expected_rows = expected_rows or {}
        self.checkpoints = list(checkpoints)
        self.arms = list(arms)
        self.checkpoint_dirs = dict(checkpoint_dirs)
        self.model_shas = dict(model_shas)
        self.score_predictions = score_predictions
        self.build_summary = build_summary
        self.run = run or _NullRun()
        self.started = started or time.time()
        self.seen = {}        # shard name -> day metrics
        self.summaries = {}   # (label, arm) -> summary
        self.step = 0

    # -- per shard -------------------------------------------------------
    def _short(self, label: str) -> str:
        for ckpt in self.checkpoints:
            if ckpt["label"] == label:
                return ckpt["short"]
        return label

    def poll_shards(self) -> list[str]:
        import pandas as pd

        new = []
        for ckpt in self.checkpoints:
            for arm in self.arms:
                for date in self.dates:
                    task = {"checkpoint": ckpt["label"], "arm": arm["name"], "date": date}
                    path = shard_file(self.shards, task)
                    if path.name in self.seen or not path.is_file():
                        continue
                    frame = pd.read_csv(path)
                    day = {}
                    try:
                        metrics = self.score_predictions(frame)["by_signal_date"]
                        day = dict(metrics[0]) if metrics else {}
                    except Exception as exc:  # noqa: BLE001 - best effort
                        day = {"metric_error": repr(exc)}
                    day["top_bottom_decile_return10d"] = top_bottom_by_date(frame).get(date)
                    day["rows"] = int(len(frame))
                    self.seen[path.name] = {"checkpoint": ckpt["label"], "arm": arm["name"],
                                            "date": date, **day}
                    self.step += 1
                    new.append(path.name)
                    done = self._ic_by_date(ckpt["label"], arm["name"])
                    running = sum(done.values()) / len(done) if done else None
                    short = ckpt["short"]
                    payload = {
                        "oos/shards_done": self.step,
                        f"oos/{short}/ret10d_ic_day": day.get("return10d_rank_ic"),
                        f"oos/{short}/ret10d_ic_running_mean": running,
                        f"oos/{short}/dates_done": len(done),
                        f"oos/{short}/top_bottom_decile_day": day["top_bottom_decile_return10d"],
                        "oos/elapsed_hours": (time.time() - self.started) / 3600.0,
                    }
                    ref = SEG155_OOS_PROD_BY_DATE.get(date)
                    if ref is not None and day.get("return10d_rank_ic") is not None:
                        payload[f"oos/{short}/ret10d_ic_day_minus_seg155"] = (
                            day["return10d_rank_ic"] - ref
                        )
                    self.run.log({k: v for k, v in payload.items() if v is not None},
                                 step=self.step)
                    phase("shard_scored", checkpoint=ckpt["label"], arm=arm["name"], date=date,
                          rows=day["rows"], return10d_rank_ic=day.get("return10d_rank_ic"),
                          top_bottom_decile=day["top_bottom_decile_return10d"],
                          running_mean=running, dates_done=len(done), shards_done=self.step)
        if new:
            self.write_progress()
        return new

    def _ic_by_date(self, label: str, arm: str) -> dict:
        return {
            item["date"]: item.get("return10d_rank_ic")
            for item in self.seen.values()
            if item["checkpoint"] == label and item["arm"] == arm
            and item.get("return10d_rank_ic") is not None
        }

    def write_progress(self) -> dict:
        progress = {
            "kernel": KERNEL_ID,
            "elapsed_sec": time.time() - self.started,
            "shards_done": self.step,
            "shards_total": len(self.checkpoints) * len(self.arms) * len(self.dates),
            "by_checkpoint": {},
        }
        for ckpt in self.checkpoints:
            for arm in self.arms:
                ic = self._ic_by_date(ckpt["label"], arm["name"])
                progress["by_checkpoint"][f"{ckpt['label']}::{arm['name']}"] = {
                    "dates_done": len(ic),
                    "running_ic_mean": (sum(ic.values()) / len(ic)) if ic else None,
                    "by_date": dict(sorted(ic.items())),
                    "scored": (ckpt["label"], arm["name"]) in self.summaries,
                }
        (self.results / "progress.json").write_text(
            json.dumps(progress, ensure_ascii=False, indent=2) + "\n"
        )
        return progress

    # -- per checkpoint --------------------------------------------------
    def score_ready(self) -> list[tuple[str, str]]:
        import pandas as pd

        finished = []
        for ckpt in self.checkpoints:
            label = ckpt["label"]
            for arm in self.arms:
                key = (label, arm["name"])
                if key in self.summaries:
                    continue
                parts = [shard_file(self.shards, {"checkpoint": label, "arm": arm["name"],
                                                  "date": date}) for date in self.dates]
                if not all(path.is_file() for path in parts):
                    continue
                frame = pd.concat([pd.read_csv(path) for path in parts], ignore_index=True)
                if len(frame) != self.records_count:
                    raise RuntimeError(
                        f"{label}/{arm['name']} row mismatch: {len(frame)} != {self.records_count}"
                    )
                metrics = self.score_predictions(frame)
                summary = self.build_summary(
                    label, Path(self.checkpoint_dirs[label]), arm, metrics,
                    time.time() - self.started, False, self.model_shas.get(label),
                )
                tb = top_bottom_by_date(frame)
                summary["use_beta_v21_auxiliary"] = None  # not inspected parent-side
                summary["top_bottom_decile_return10d"] = sum(tb.values()) / len(tb)
                summary["top_bottom_decile_by_date"] = tb
                summary["val_gen_ic_daily"] = ckpt.get("val_gen_ic_daily")
                summary["full_val_wfl"] = ckpt.get("full_val_wfl")
                summary["checkpoint_note"] = ckpt.get("note")
                ic = {row["asof_date"]: row["return10d_rank_ic"]
                      for row in summary["by_signal_date"]}
                summary["vs_reference_paired"] = {
                    name: paired_stats(ic, series) for name, series in REFERENCE_SERIES.items()
                }
                self.summaries[key] = summary
                stem = f"{label}_{arm['name']}"
                frame.to_csv(self.results / f"{stem}_predictions.csv.gz", index=False,
                             compression="gzip")
                pd.DataFrame(summary["by_signal_date"]).assign(
                    top_bottom_decile_return10d=lambda d: d["asof_date"].map(tb)
                ).to_csv(self.results / f"{stem}_by_date.csv", index=False)
                (self.results / f"{stem}_summary.json").write_text(
                    json.dumps(summary, ensure_ascii=False, indent=2, default=str) + "\n"
                )
                short = ckpt["short"]
                self.run.log({k: v for k, v in {
                    f"oos_final/{short}/ret10d_ic_daily": summary["return10d_rank_ic_daily"],
                    f"oos_final/{short}/ret10d_ic_pooled": summary["return10d_rank_ic_pooled"],
                    f"oos_final/{short}/ret10d_icir": summary["return10d_rank_icir"],
                    f"oos_final/{short}/ret10d_ic_pos_rate": summary["return10d_rank_ic_pos_rate"],
                    f"oos_final/{short}/top_bottom_decile": summary["top_bottom_decile_return10d"],
                    f"oos_final/{short}/utility_ic_daily": summary["utility_rank_ic_daily"],
                    f"oos_final/{short}/pairwise_accuracy": summary["pairwise_accuracy"],
                }.items() if v is not None}, step=max(self.step, 1))
                phase("checkpoint_scored", checkpoint=label, arm=arm["name"],
                      samples=summary["samples"], signal_dates=summary["signal_dates"],
                      return10d_rank_ic_daily=summary["return10d_rank_ic_daily"],
                      return10d_rank_ic_pooled=summary["return10d_rank_ic_pooled"],
                      return10d_rank_icir=summary["return10d_rank_icir"],
                      return10d_rank_ic_pos_rate=summary["return10d_rank_ic_pos_rate"],
                      top_bottom_decile=summary["top_bottom_decile_return10d"],
                      utility_rank_ic_daily=summary["utility_rank_ic_daily"],
                      pairwise_accuracy=summary["pairwise_accuracy"],
                      vs_seg155=summary["vs_reference_paired"]["seg155_forecast_best_prod"],
                      vs_c2=summary["vs_reference_paired"]["small_c2_best_prod"])
                finished.append(key)
                self.write_comparison(final=False)
        return finished

    def primary_pair(self) -> dict | None:
        out = {}
        for arm in self.arms:
            a = self.summaries.get((PRIMARY_PAIR[0], arm["name"]))
            b = self.summaries.get((PRIMARY_PAIR[1], arm["name"]))
            if a is None or b is None:
                continue
            ia = {r["asof_date"]: r["return10d_rank_ic"] for r in a["by_signal_date"]}
            ib = {r["asof_date"]: r["return10d_rank_ic"] for r in b["by_signal_date"]}
            out[arm["name"]] = {"a": PRIMARY_PAIR[0], "b": PRIMARY_PAIR[1],
                                **(paired_stats(ia, ib) or {})}
        return out or None

    def write_comparison(self, final: bool) -> dict:
        incomplete = []
        for ckpt in self.checkpoints:
            for arm in self.arms:
                if (ckpt["label"], arm["name"]) in self.summaries:
                    continue
                have = sum(
                    1 for date in self.dates
                    if shard_file(self.shards, {"checkpoint": ckpt["label"],
                                                "arm": arm["name"], "date": date}).is_file()
                )
                incomplete.append({"checkpoint": ckpt["label"], "arm": arm["name"],
                                   "have": have, "need": len(self.dates)})
        pair = self.primary_pair()
        comparison = {
            "evaluation_name": EXPECTED_EVAL_NAME,
            "baseline": "baseline_2_generative_return",
            "training": False,
            "kernel": KERNEL_ID,
            "preregistration": PREREGISTRATION,
            "checkpoint_order": [ckpt["label"] for ckpt in self.checkpoints],
            "model_sha256": self.model_shas,
            "arms": [arm["name"] for arm in self.arms],
            "checkpoints": [
                self.summaries[(ckpt["label"], arm["name"])]
                for ckpt in self.checkpoints for arm in self.arms
                if (ckpt["label"], arm["name"]) in self.summaries
            ],
            "primary_pair_seg9_minus_seg0": pair,
            "reference_series": REFERENCE_SERIES,
            "incomplete": incomplete,
            "final": final,
            "elapsed_sec": time.time() - self.started,
        }
        (self.results / "comparison.json").write_text(
            json.dumps(comparison, ensure_ascii=False, indent=2, default=str) + "\n"
        )
        shutil.copy2(self.results / "comparison.json", self.working / "comparison.json")
        if pair:
            for arm_name, stats in pair.items():
                self.run.log({k: v for k, v in {
                    "oos_final/seg9_minus_seg0": stats.get("mean_diff"),
                    "oos_final/seg9_minus_seg0_t": stats.get("t"),
                    "oos_final/seg9_minus_seg0_wins": stats.get("wins"),
                }.items() if v is not None}, step=max(self.step, 1))
        return comparison


def parent_main() -> None:
    started = time.time()
    working = WORKING_ROOT / OUTPUT_NAME
    working.mkdir(parents=True, exist_ok=True)
    shards = working / "shards"
    shards.mkdir(exist_ok=True)
    claims = working / "claims"
    claims.mkdir(exist_ok=True)
    (working / "results").mkdir(exist_ok=True)

    if not LOCAL_TEST:
        gpu_names = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"], text=True
        ).strip().splitlines()
        if len(gpu_names) != WORLD_SIZE or any("T4" not in name for name in gpu_names):
            raise RuntimeError(f"Expected exactly two Tesla T4 GPUs, found {gpu_names}")
        phase("gpu", names=gpu_names)
    phase("start", experiment=EXPERIMENT_NAME, kernel=KERNEL_ID, local_test=LOCAL_TEST,
          order=[ckpt["label"] for ckpt in CHECKPOINTS], swanlab=SWANLAB_URL)

    repo = extract_bundle(working / "src")
    sys.path.insert(0, str(repo))
    sys.path.insert(0, str(repo / "finetune"))

    from evaluate_beta_v21_generative_return_oos import ARMS, build_summary, score_predictions
    from evaluate_beta_v21_time_oos import find_evaluation_root, load_incremental_records

    snapshot = download_model_repo(working / "pretrained")
    tokenizer = resolve_tokenizer(snapshot)
    checkpoint_dirs, model_shas = {}, {}
    for ckpt in CHECKPOINTS:
        if ckpt["source"] == "modelscope":
            path = resolve_release_predictor(snapshot, ckpt["sha256"])
        else:
            path = find_dataset_checkpoint(INPUT_ROOT, ckpt["label"], ckpt["patterns"])
        model_shas[ckpt["label"]] = check_sha(ckpt["label"], path / "model.safetensors",
                                              ckpt["sha256"])
        checkpoint_dirs[ckpt["label"]] = str(path)
        phase("checkpoint_ready", label=ckpt["label"], source=ckpt["source"], path=str(path),
              sha256=model_shas[ckpt["label"]])

    evaluation_root, manifest = find_evaluation_root(INPUT_ROOT)
    samples_path = evaluation_root / manifest["artifacts"]["samples_file"]
    records = load_incremental_records(samples_path, manifest)
    dates = sorted({row["asof_date"] for row in records})
    if manifest.get("name") != EXPECTED_EVAL_NAME:
        raise RuntimeError(f"Unexpected eval name: {manifest.get('name')}")
    if not LOCAL_TEST and (len(dates) != EXPECTED_SIGNAL_DATES or len(records) != EXPECTED_SAMPLES):
        raise RuntimeError(
            f"Expected {EXPECTED_SIGNAL_DATES} dates / {EXPECTED_SAMPLES} samples, "
            f"found {len(dates)} / {len(records)}"
        )

    active_arms = [arm for arm in ARMS if ARM_FILTER is None or arm["name"] in ARM_FILTER]
    if not active_arms:
        raise RuntimeError(f"ARM_FILTER matched nothing: {ARM_FILTER}")
    tasks = build_tasks(CHECKPOINTS, active_arms, dates)
    plan_path = working / "plan.json"
    plan = {
        "repo": str(repo),
        "tokenizer_dir": str(tokenizer),
        "checkpoints": checkpoint_dirs,
        "checkpoint_order": [ckpt["label"] for ckpt in CHECKPOINTS],
        "evaluation_root": str(evaluation_root),
        "shards": str(shards),
        "claims": str(claims),
        "dynamic_claims": True,
        "deadline": started + HARD_LIMIT_SECONDS,
        "effective_batch": EFFECTIVE_BATCH,
        "tasks": tasks,
        "score_definition": (
            "predicted_return_d10 = mean_N AR samples of "
            "(denorm_close_d10 / last_close - 1); NOT return_head; NOT teacher-forcing"
        ),
        "arms": active_arms,
        "preregistration": PREREGISTRATION,
        "reference_series": REFERENCE_SERIES,
        "kernel": KERNEL_ID,
    }
    plan_path.write_text(json.dumps(plan, ensure_ascii=False, indent=2) + "\n")
    phase("inputs_resolved", evaluation_name=EXPECTED_EVAL_NAME, signal_dates=len(dates),
          records=len(records), arms=[arm["name"] for arm in active_arms], tasks=len(tasks),
          model_sha256=model_shas, effective_batch=EFFECTIVE_BATCH, training=False)

    swanlab, run = start_swanlab({
        "kernel": KERNEL_ID,
        "evaluation_name": EXPECTED_EVAL_NAME,
        "checkpoint_order": [ckpt["label"] for ckpt in CHECKPOINTS],
        "model_sha256": model_shas,
        "arm": [arm["name"] for arm in active_arms],
        "signal_dates": len(dates),
        "records": len(records),
        "effective_batch": EFFECTIVE_BATCH,
        "seg155_oos_prod_ic": 0.11702,
        "c2_oos_prod_ic": 0.17687,
        "role": PREREGISTRATION["role"],
    })

    worker_script = repo / "finetune" / "evaluate_beta_v21_generative_return_oos.py"
    processes = []
    for rank in range(WORLD_SIZE):
        environment = os.environ.copy()
        environment.update({
            "PYTHONUNBUFFERED": "1",
            "CUDA_VISIBLE_DEVICES": str(rank),
            "KRONOS_SWEEP_RANK": str(rank),
            "KRONOS_SWEEP_WORLD": str(WORLD_SIZE),
            "PYTHONPATH": os.pathsep.join(
                [str(repo), str(repo / "finetune"), environment.get("PYTHONPATH", "")]
            ),
        })
        processes.append(subprocess.Popen(
            [sys.executable, "-u", str(worker_script), "--worker-plan", str(plan_path)],
            env=environment,
        ))
    phase("workers_spawned", n=WORLD_SIZE, script=str(worker_script), mode="dynamic_claims")

    scorer = OOSScorer(working, shards, dates, records_count=0, checkpoints=CHECKPOINTS,
                       arms=active_arms, checkpoint_dirs=checkpoint_dirs,
                       model_shas=model_shas, score_predictions=score_predictions,
                       build_summary=build_summary, run=run, started=started)
    scorer.records_count = len(records)
    scorer.write_progress()
    scorer.write_comparison(final=False)

    while True:
        codes = [process.poll() for process in processes]
        scorer.poll_shards()
        scorer.score_ready()
        if all(code is not None for code in codes):
            break
        if any(code not in (None, 0) for code in codes):
            phase("worker_failed", codes=codes)
            for process in processes:
                if process.poll() is None:
                    process.wait()
            break
        time.sleep(POLL_SECONDS)
    failures = [process.wait() for process in processes]
    scorer.poll_shards()
    scorer.score_ready()
    comparison = scorer.write_comparison(final=True)
    phase("comparison_final", primary_pair=comparison["primary_pair_seg9_minus_seg0"],
          incomplete=comparison["incomplete"],
          headline={c["label"]: c["return10d_rank_ic_daily"] for c in comparison["checkpoints"]})
    if swanlab is not None:
        try:
            swanlab.finish()
        except Exception as error:  # noqa: BLE001
            phase("swanlab_finish_error", error=repr(error))
    if any(code != 0 for code in failures):
        raise RuntimeError(f"Worker exit codes: {failures}")
    if not scorer.summaries:
        raise RuntimeError(f"No checkpoint completed: {comparison['incomplete']}")
    if comparison["incomplete"]:
        phase("partial", incomplete=comparison["incomplete"])
    phase("done", total_seconds=round(time.time() - started, 1), swanlab=SWANLAB_URL)


def main() -> None:
    parent_main()


if __name__ == "__main__":
    main()
